<script setup lang="ts">
import {Head,Link,router} from '@inertiajs/vue3';import {Clock3,BookOpen,ArrowRight,Compass,Trash2} from 'lucide-vue-next';import {prettyDate,readPercent} from '../utils';
interface Item{id:number;manga_id:string;chapter_id:string;manga_title:string|null;chapter_name:string|null;page_number:number;total_pages:number;updated_at:string}
const props=defineProps<{items:Item[]}>();
function clearAll(){if(confirm('¿Eliminar TODO el historial de lectura? Los mangas de tu biblioteca no se borrarán.'))router.delete('/history');}
function remove(it:Item){if(confirm('¿Quitar este capítulo del historial?'))router.delete(`/history/${it.id}`,{preserveScroll:true});}
</script>
<template><Head title="Historial"/><div class="content"><div class="page-head"><div><div class="eyebrow">✦ Continuar leyendo</div><h1>Historial de lectura</h1><p class="lead">Reanudá tus capítulos. El progreso se guarda en MySQL y pertenece a tu cuenta.</p></div><div class="page-controls"><span class="pill"><Clock3 :size="15"/> {{items.length}} registros</span><button v-if="items.length" class="button danger" @click="clearAll"><Trash2/> Limpiar historial</button></div></div>
<div v-if="items.length" class="table-rows"><div v-for="it in items" :key="it.id" class="history-item"><Link :href="`/manga/${it.manga_id}/read/${it.chapter_id}`" style="display:flex;align-items:center;gap:14px;flex:1;min-width:0"><div class="badge-icon"><BookOpen :size="21"/></div><div style="flex:1;min-width:0"><p class="history-title">{{it.manga_title||`Manga #${it.manga_id}`}}</p><div class="history-sub">{{it.chapter_name||`Capítulo ${it.chapter_id}`}} · {{prettyDate(it.updated_at)}}</div><div style="display:flex;align-items:center;gap:10px"><div class="progress-track" style="max-width:400px;flex:1"><div class="progress-fill" :style="{width:readPercent(it.page_number,it.total_pages)+'%'}"/></div><span class="tiny">Página {{it.page_number}} / {{it.total_pages}}</span></div></div><ArrowRight :size="19" class="muted"/></Link><button class="button danger" @click="remove(it)" title="Eliminar del historial"><Trash2/></button></div></div>
<div v-else class="empty"><div class="empty-icon"><Clock3/></div><h3>Aún no hay lecturas registradas</h3><p>Empezá un capítulo para que aparezca aquí.</p><Link href="/explore" class="button primary"><Compass/> Explorar</Link></div></div></template>
